// Manual annotations are independent of engine output and chess legality.
export function toggleArrow(arrows,from,to){if(!/^[a-h][1-8]$/.test(from)||!/^[a-h][1-8]$/.test(to)||from===to)return arrows;return arrows.some(a=>a.from===from&&a.to===to)?arrows.filter(a=>a.from!==from||a.to!==to):[...arrows,{from,to}]}
export function pointFor(s,flip=false){const f=s.charCodeAt(0)-97,r=+s[1]-1;return[(flip?7-f:f)*100+50,(flip?r:7-r)*100+50]}
const mounted=new WeakSet();let serial=0;
export function mountAnnotations(board){if(mounted.has(board))return;mounted.add(board);let arrows=[],start=null,preview=null,mode=false,signature='',tap=null;const ns='http://www.w3.org/2000/svg',id='manual-head-'+(++serial),svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 800 800');svg.setAttribute('aria-hidden','true');svg.classList.add('manual-arrows');const toolbar=document.createElement('div');toolbar.className='annotation-tools';toolbar.innerHTML='<button type="button" aria-pressed="false">Disegna frecce</button><button type="button">Cancella frecce</button><small>Tasto destro e trascina · oppure attiva e tocca due case</small>';const[toggle,clear]=toolbar.querySelectorAll('button');(board.closest('.board-wrap')||board).after(toolbar);
 function paint(){const flip=board.querySelector('[data-sq]')?.dataset.sq==='h1';svg.innerHTML=`<defs><marker id="${id}" markerWidth="3" markerHeight="3" refX="2.4" refY="1.5" orient="auto"><path d="M0,0 L3,1.5 L0,3Z" fill="#61d7ef"/></marker></defs>`;for(const a of [...arrows,...(preview?[preview]:[])]){const[x,y]=pointFor(a.from,flip),[tx,ty]=pointFor(a.to,flip),line=document.createElementNS(ns,'line');for(const[k,v]of Object.entries({x1:x,y1:y,x2:tx,y2:ty,stroke:'#61d7ef','stroke-width':12,'stroke-linecap':'round','stroke-dasharray':'18 9','marker-end':`url(#${id})`,opacity:a===preview?.65:.9}))line.setAttribute(k,String(v));svg.append(line)}if(svg.parentElement!==board)board.append(svg);clear.disabled=!arrows.length&&!tap}
 function square(e){const r=board.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/r.width*8),y=Math.floor((e.clientY-r.top)/r.height*8);if(x<0||x>7||y<0||y>7)return null;const flip=board.querySelector('[data-sq]')?.dataset.sq==='h1';return'abcdefgh'[flip?7-x:x]+(flip?y+1:8-y)}
 toggle.onclick=()=>{mode=!mode;tap=null;board.classList.toggle('annotating',mode);toggle.setAttribute('aria-pressed',String(mode));toggle.textContent=mode?'Termina disegno':'Disegna frecce'};clear.onclick=()=>{arrows=[];tap=null;preview=null;paint()};board.addEventListener('contextmenu',e=>e.preventDefault());
 board.addEventListener('pointerdown',e=>{if(e.button!==2&&!mode)return;start=square(e);if(!start)return;e.preventDefault();e.stopImmediatePropagation();board.setPointerCapture(e.pointerId)},true);
 board.addEventListener('pointermove',e=>{if(!start)return;const to=square(e);preview=to&&to!==start?{from:start,to}:null;paint();e.preventDefault()},true);
 board.addEventListener('pointerup',e=>{if(!start)return;e.preventDefault();e.stopImmediatePropagation();const to=square(e);if(to&&start!==to){arrows=toggleArrow(arrows,start,to);tap=null}else if(mode&&to){if(tap&&tap!==to){arrows=toggleArrow(arrows,tap,to);tap=null}else tap=to}start=null;preview=null;paint();if(board.hasPointerCapture(e.pointerId))board.releasePointerCapture(e.pointerId)},true);
 board.addEventListener('pointercancel',()=>{start=null;preview=null;paint()});board.addEventListener('click',e=>{if(mode){e.preventDefault();e.stopImmediatePropagation()}},true);
 board.addEventListener('board-updated',()=>{const next=[...board.querySelectorAll('[data-sq]')].map(s=>s.dataset.sq+':'+(s.querySelector('img')?.getAttribute('src')||'')).sort().join('|');if(signature&&signature!==next){arrows=[];tap=null;preview=null;start=null}signature=next;paint()});paint();
}
if(typeof document!=='undefined')document.querySelectorAll('.board').forEach(mountAnnotations);
